class Solution {
public:
    int findTheWinner(int n, int k) {
        int winner = 0; // 0-indexed Josephus position for size 1
        for (int i = 2; i <= n; ++i) {
            winner = (winner + k) % i;
        }
        return winner + 1; // convert to 1-indexed friend number
    }
};
